<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nueva entrega</title><style>body{font-family:system-ui;background:#f3f6fa;color:#173454;margin:0;padding:25px}main{max-width:1000px;margin:auto;background:white;padding:28px;border-radius:14px;box-shadow:0 3px 16px #1b355015}a{color:#125aa2}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e4eaf1;text-align:left}input,select,textarea{padding:9px;border:1px solid #aabbd0;border-radius:6px}input[type=number]{width:110px}button{background:#145b9d;color:white;padding:12px 18px;border:0;border-radius:6px;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}.fila{display:flex;justify-content:space-between;align-items:center;padding:5px;border-bottom:1px solid #edf0f5}.error{color:#ae2929}</style></head><body><main><p><a href="{{ route('receptor.entregas.index') }}">Volver</a></p><h1>Entrega de efectivo entre receptores</h1><p>El receptor saliente registra el conteo y firma. El receptor entrante confirma después y Caja certifica. No se ejecutan movimientos bancarios.</p>@if($errors->any())<ul class="error">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="post" action="{{ route('receptor.entregas.store') }}">@csrf<p><label>Turno del receptor saliente<br><select name="jornada_id" required><option value="">Seleccione su turno</option>@foreach($salientes as $j)<option value="{{ $j->id }}" @selected(old('jornada_id')==$j->id)>{{ $j->agencia->nombre }} · {{ $j->ventanilla->codigo }} · {{ $j->turno->nombre }}</option>@endforeach</select></label></p><p><label>Turno del receptor entrante (misma agencia y ventanilla)<br><select name="jornada_entrante_id" required><option value="">Seleccione el turno entrante</option>@foreach($jornadas as $j)<option value="{{ $j->id }}" @selected(old('jornada_entrante_id')==$j->id)>{{ $j->agencia->nombre }} · {{ $j->ventanilla->codigo }} · {{ $j->receptor->nombre_completo }} · {{ $j->turno->nombre }}</option>@endforeach</select></label></p><div class="grid"><section><h2>Billetes</h2>@foreach($billetes as $v)<div class="fila"><label>Q {{ $v }}</label><input type="number" name="billetes[{{ $v }}]" value="{{ old('billetes.'.$v,0) }}" min="0" max="10000000" required></div>@endforeach</section><section><h2>Monedas</h2>@foreach($monedas as $v)<div class="fila"><label>Q {{ $v }}</label><input type="number" name="monedas[{{ $v }}]" value="{{ old('monedas.'.$v,0) }}" min="0" max="10000000" required></div>@endforeach</section></div><p><label>Monto de referencia del corte (Q)<br><input type="number" step="0.01" min="0" name="total_corte" value="{{ old('total_corte','0.00') }}" required></label></p><p><label>Justificación de diferencia<br><textarea name="justificacion_diferencia" rows="3" style="width:95%">{{ old('justificacion_diferencia') }}</textarea></label></p><p><label>Observaciones<br><textarea name="observaciones" rows="3" style="width:95%">{{ old('observaciones') }}</textarea></label></p><p><label><input type="checkbox" name="confirmar" value="1" required> Confirmo el conteo y firmo como receptor saliente.</label></p><button type="submit">Registrar y firmar entrega</button></form></main></body></html>